    var cs = getComputedStyle(el);

    keys.forEach(function (k) {
      var end = props[k];
      if (COLOR_PROPS.test(k)) {
        var c0 = parseColor(cs.getPropertyValue(k.replace(/[A-Z]/g, function (m2) { return "-" + m2.toLowerCase(); })) || cs[k] || "#000");
        var c1 = parseColor(end);
        if (c0 && c1) { startVals[k] = c0; endVals[k] = c1; return; }
      }
      var s = parseFloat(cs[k]);
      var e = parseFloat(end);
      if (!isNaN(s) && !isNaN(e)) {
        var unit = String(end).replace(/[-\d.]/g, "") || (String(cs[k]).match(/[a-z%]+$/) || [""])[0];
        startVals[k] = s; endVals[k] = { v: e, u: unit };
      } else {
        el.style[k] = end;
      }
    });

    if (dur <= 0) {
      keys.forEach(function (k) {
        if (endVals[k] && typeof endVals[k] === "object" && "v" in endVals[k]) el.style[k] = endVals[k].v + endVals[k].u;
        else if (endVals[k] && endVals[k].r != null) el.style[k] = fmtColor(endVals[k]);
        else el.style[k] = props[k];
      });
      if (onDone) onDone();
      return;
    }

    var t0 = null;
    var raf = 0;
    function frame(ts) {
      if (t0 == null) t0 = ts;
      var elapsed = ts - t0 - delay;
      if (elapsed < 0) { raf = requestAnimationFrame(frame); return; }
      var p = Math.min(1, elapsed / dur);
      var e = ease(p);
      keys.forEach(function (k) {
        var sv = startVals[k], ev = endVals[k];
        if (ev && ev.r != null) {
          el.style[k] = fmtColor({
            r: lerp(sv.r, ev.r, e), g: lerp(sv.g, ev.g, e), b: lerp(sv.b, ev.b, e),
            a: lerp(sv.a == null ? 1 : sv.a, ev.a == null ? 1 : ev.a, e),
          });
        } else if (ev && "v" in ev) {
          el.style[k] = lerp(sv, ev.v, e) + ev.u;
        } else {
          el.style[k] = props[k];
        }
      });
      if (p < 1) raf = requestAnimationFrame(frame);
      else if (onDone) onDone();
    }
    raf = requestAnimationFrame(frame);
    return function cancel() { cancelAnimationFrame(raf); };
  }

  function countTo(el, to, opts) {
    opts = opts || {};
    var from = opts.from != null ? opts.from : (parseFloat(String(el.textContent).replace(/[^\d.-]/g, "")) || 0);
    var dur = opts.duration != null ? opts.duration : 600;
    var ease = typeof opts.ease === "function" ? opts.ease : Ease.cubicOut;
    var decimals = opts.decimals != null ? opts.decimals : 0;
    var prefix = opts.prefix || "";
    var suffix = opts.suffix || "";
    var sep = opts.sep !== false;
    function fmt(n) {
      var s = Math.abs(n).toFixed(decimals);
      if (sep) s = s.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
      return (n < 0 ? "-" : "") + prefix + s + suffix;
    }
    if (!el) return;
    if (dur <= 0) { el.textContent = fmt(to); return; }
    var t0 = null, raf = 0;
    function frame(ts) {
      if (t0 == null) t0 = ts;
      var p = Math.min(1, (ts - t0) / dur);
      el.textContent = fmt(from + (to - from) * ease(p));
      if (p < 1) raf = requestAnimationFrame(frame);
    }
    raf = requestAnimationFrame(frame);
    return function cancel() { cancelAnimationFrame(raf); };
  }

  function seq(fns, gap) {
    gap = gap == null ? 80 : gap;
    var i = 0;
    function next() {
      if (i >= fns.length) return;
      var fn = fns[i++];
      try { fn(); } catch (e) { /* keep going */ }
      if (i < fns.length) setTimeout(next, gap);
    }
    next();
  }

  window.UXTween = { to: tween, count: countTo, seq: seq, ease: Ease };

  /* ── 屏幕路由 ───────────────────────────────── */
  function collect() {
    screenEls = $$(".ux-screen", app);
    screenEls.forEach(function (el) {
      screens[el.getAttribute("data-screen")] = el;
    });
  }

  function setActiveTab(id) {
    $$("[data-goto-tab]", app).forEach(function (el) {
      el.classList.toggle("is-active", el.getAttribute("data-goto-tab") === id);
    });
  }

  function runScreenHooks(el) {
    if (!el) return;
    // progress bars
    $$(".ux-progress__bar[data-value]", el).forEach(function (bar) {
      if (bar.classList.contains("is-indeterminate")) return;
      var v = parseFloat(bar.getAttribute("data-value")) || 0;
      bar.style.width = "0%";
      requestAnimationFrame(function () {
        requestAnimationFrame(function () { bar.style.width = Math.max(0, Math.min(100, v * 100)) + "%"; });
      });
    });
    // chart bars
    $$(".ux-chart__bar[data-h]", el).forEach(function (bar) {
      var h = parseFloat(bar.getAttribute("data-h")) || 0;
      bar.style.height = "0%";
      requestAnimationFrame(function () {
        requestAnimationFrame(function () { bar.style.height = Math.max(2, Math.min(100, h)) + "%"; });
      });
    });
    // exp / hp fills
    $$(".ux-player__exp > i[data-value], .ux-hp__fill[data-value]", el).forEach(function (fill) {
      var v = parseFloat(fill.getAttribute("data-value")) || 0;
      var target = Math.max(0, Math.min(100, v * 100)) + "%";
      fill.style.width = "0%";
      requestAnimationFrame(function () {
        requestAnimationFrame(function () { fill.style.width = target; });
      });
    });
    // number counters
    $$("[data-count-to]", el).forEach(function (n) {
      var to = parseFloat(n.getAttribute("data-count-to"));
      var from = parseFloat(n.getAttribute("data-count-from") || "0");
      if (!isNaN(to)) countTo(n, to, { from: from, duration: 700, prefix: n.getAttribute("data-count-prefix") || "", suffix: n.getAttribute("data-count-suffix") || "" });
    });
    // stagger containers
    $$("[data-stagger]", el).forEach(function (c) {
      // restart animation by reflow
      c.style.animation = "none";
      void c.offsetWidth;
      c.style.animation = "";
    });
    // demo: hp drain
    if (app.getAttribute("data-demo-hp") === "1") {
      $$("[data-demo-drain]", el).forEach(function (fill) {
        var v = parseFloat(fill.getAttribute("data-value")) || 1;
        setTimeout(function () { fill.style.width = Math.max(8, v * 0.62 * 100) + "%"; }, 900);
      });
    }
  }

  function go(id, opts) {
    opts = opts || {};
    if (!screens[id]) return;
    if (id === current && !opts.force) return;
    var from = current ? screens[current] : null;
    var to = screens[id];
    if (from && !opts.back) history.push(current);
    if (from) {
      from.classList.remove("is-active");
      from.classList.toggle("is-back", !opts.back);
    }
    to.classList.remove("is-back");
    to.classList.add("is-active");
    var sc = $(".ux-scroll", to);
    if (sc && !opts.keepScroll) sc.scrollTop = 0;
    current = id;
    setActiveTab(id);
    runScreenHooks(to);
    try { doc.title = (app.getAttribute("data-title") || "原型") + " · " + (to.getAttribute("data-title") || id); } catch (e) {}
  }

  function back() {
    if (history.length > 1) {
      history.pop();
      var prev = history[history.length - 1];
      go(prev, { back: true, force: true });
    } else if (history.length === 1) {
      history.pop();
      var first = screenEls.length ? screenEls[0].getAttribute("data-screen") : current;
      go(first, { back: true, force: true });
    }
  }

  /* toast */
  var toastEl = $(".ux-toast", app);
  var toastTimer = null;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("is-open");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { toastEl.classList.remove("is-open"); }, 1900);
  }

  /* modal */
  var modalEl = $(".ux-modal", app);
  function openModal(title, body, okLabel, onOk) {
    if (!modalEl) { toast(title); return; }
    $(".ux-modal__title", modalEl).textContent = title || "";
    $(".ux-modal__body", modalEl).textContent = body || "";
    var okBtn = $("[data-modal-ok]", modalEl);
    if (okLabel) okBtn.textContent = okLabel;
    modalEl.classList.add("is-open");
    modalEl._onOk = onOk || null;
  }
  function closeModal() { if (modalEl) modalEl.classList.remove("is-open"); }
  if (modalEl) {
    $$("[data-modal-close]", modalEl).forEach(function (b) {
      b.addEventListener("click", function () { closeModal(); });
    });
    var okb = $("[data-modal-ok]", modalEl);
    if (okb) okb.addEventListener("click", function () {
      var fn = modalEl._onOk;
      closeModal();
      if (typeof fn === "function") fn();
    });
  }

  /* segmented control */
  function wireSegs(root) {
    $$(".ux-seg", root || app).forEach(function (seg) {
      $$(".ux-seg__item", seg).forEach(function (item) {
        item.addEventListener("click", function () {
          $$(".ux-seg__item", seg).forEach(function (i) { i.classList.remove("is-active"); });
          item.classList.add("is-active");
        });
      });
    });
  }

  /* toggles */
  function wireToggles(root) {
    $$(".ux-toggle", root || app).forEach(function (t) {
      if (t._wired) return;
      t._wired = true;
      t.setAttribute("role", "switch");
      t.setAttribute("tabindex", "0");
      function flip() {
        t.classList.toggle("is-on");
        t.setAttribute("aria-checked", t.classList.contains("is-on") ? "true" : "false");
      }
      t.addEventListener("click", flip);
      t.addEventListener("keydown", function (e) {
        if (e.key === "Enter" || e.key === " ") { e.preventDefault(); flip(); }
      });
    });
  }

  /* state switcher */
  function wireStateSwitchers(root) {
    $$(".ux-state-switch", root || app).forEach(function (sw) {
      var hostId = sw.getAttribute("data-for");
      var host = hostId ? doc.getElementById(hostId) : sw.parentElement.querySelector(".ux-state-host");
      if (!host) return;
      var btns = $$(".ux-state-switch__btn", sw);
      btns.forEach(function (btn) {
        btn.addEventListener("click", function () {
          var state = btn.getAttribute("data-state") || "ready";
          btns.forEach(function (b) { b.classList.toggle("is-active", b === btn); });
          $$(".ux-state-view", host).forEach(function (v) {
            v.classList.toggle("is-shown", v.getAttribute("data-state") === state);
          });
          var shown = host.querySelector('.ux-state-view.is-shown [data-value], .ux-state-view.is-shown .ux-progress__bar');
          runScreenHooks(host);
        });
      });
    });
  }

  /* global click delegation */
  app.addEventListener("click", function (e) {
    var t = e.target.closest ? e.target.closest("[data-goto],[data-act],[data-goto-tab]") : null;
    if (!t) return;
    var tab = t.getAttribute("data-goto-tab");
    var goto = t.getAttribute("data-goto");
    var act = t.getAttribute("data-act");
    if (tab) {
      history.length = 0;
      go(tab, { force: true });
      history.push(tab);
      return;
    }
    if (goto) { go(goto); return; }
    if (act === "back") { e.preventDefault(); back(); return; }
    if (act === "orientation") {
      e.preventDefault();
      var nextOrientation = toggleOrientation();
      toast(nextOrientation === "landscape" ? "已切换横屏" : "已切换竖屏");
      return;
    }
    if (act === "toast") {
      e.preventDefault();
      toast(t.getAttribute("data-toast") || "已触发");
      if (t.classList.contains("anim-once") || t.getAttribute("data-anim-once")) {
        var cls = t.getAttribute("data-anim-once") || "anim-pop";
        t.classList.remove(cls);
        void t.offsetWidth;
        t.classList.add(cls);
      }
      return;
    }
    if (act === "modal") {
      e.preventDefault();
      openModal(t.getAttribute("data-modal-title") || "提示", t.getAttribute("data-modal-body") || "", t.getAttribute("data-modal-ok") || "确定");
      return;
    }
    if (act === "form") {
      e.preventDefault();
      toast(t.getAttribute("data-toast") || "提交成功");
      return;
    }
    if (act === "skill") {
      e.preventDefault();
      var cd = t.getAttribute("data-cd");
      toast((t.getAttribute("data-name") || "技能") + (cd ? " 冷却中 " + cd + "s" : " 已释放"));
      t.classList.remove("anim-pop");
      void t.offsetWidth;
      t.classList.add("anim-pop");
      return;
    }
    if (act === "shake") {
      e.preventDefault();
      var target = t.getAttribute("data-shake-target") ? doc.querySelector(t.getAttribute("data-shake-target")) : t;
      if (target) {
        target.classList.remove("anim-shake");
        void target.offsetWidth;
        target.classList.add("anim-shake");
      }
      return;
    }
  });

  /* form submit */
  $$("form.ux-form", app).forEach(function (f) {
    f.addEventListener("submit", function (e) {
      e.preventDefault();
      toast(f.getAttribute("data-toast") || "提交成功");
    });
  });

  collect();
  if (screenEls.length) {
    var firstId = screenEls[0].getAttribute("data-screen");
    var initial = app.getAttribute("data-initial");
    var start = initial && screens[initial] ? initial : firstId;
    screens[start].classList.add("is-active");
    current = start;
    history.push(start);
    setActiveTab(start);
    runScreenHooks(screens[start]);
  }
  wireSegs();
  wireToggles();
  wireStateSwitchers();

  window.UX = { go: go, back: back, toast: toast, tween: tween, count: countTo, seq: seq, ease: Ease, openModal: openModal, closeModal: closeModal, setOrientation: setOrientation, toggleOrientation: toggleOrientation };
})();

/* game-blocks.mjs — 游戏玩法 block 的确定性 HTML 渲染器（零依赖） */

const number = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;
const clamp = (value, min, max) => Math.max(min, Math.min(max, value));

function statusList(unit) {
  return (unit.statuses || []).map((status) => {
    const item = typeof status === "string" ? { label: status } : status;
    return { icon: item.icon || "", label: item.label || item.name || "", tone: item.tone || "accent" };
  }).filter((item) => item.label || item.icon);
}

export function renderGameBlock(block, ctx, { esc, iconHtml }) {
  const p = block.props || {};
  const art = (value, size = 24, fallback = "✦") => value ? iconHtml(value, size) : esc(fallback);
  const iconName = (value, fallback = "✦") => value || fallback;

  function unitData(unit) {
    const maxHp = Math.max(1, number(unit.maxHp ?? unit.max ?? unit.hp, 100));
    const hp = clamp(number(unit.hp, maxHp), 0, maxHp);
    return [
      `data-unit-id="${esc(unit.id || unit.name || "unit")}"`,
      `data-name="${esc(unit.name || "单位")}"`,
      `data-icon="${esc(iconName(unit.icon))}"`,
      `data-hp="${hp}"`,
      `data-max-hp="${maxHp}"`,
      `data-attack="${Math.max(0, number(unit.attack, 1))}"`,
      `data-cost="${Math.max(0, number(unit.cost, 1))}"`,
      `data-star="${Math.max(1, number(unit.star, 1))}"`,
      `data-team="${esc(unit.team || "player")}"`,
      `data-trait="${esc(unit.trait || "")}"`,
    ].join(" ");
  }

  function healthHtml(unit) {
    const maxHp = Math.max(1, number(unit.maxHp ?? unit.max ?? unit.hp, 100));
    const hp = clamp(number(unit.hp, maxHp), 0, maxHp);
    return `<span class="ux-unit-health" aria-label="生命 ${hp} / ${maxHp}"><i data-hp-fill style="width:${hp / maxHp * 100}%"></i></span><span class="ux-unit-health__text" data-hp-text>${hp}/${maxHp}</span>`;
  }

  function miniOverhead(unit) {
    const statuses = statusList(unit).map((item) =>
      `<span class="ux-unit__status" data-tone="${esc(item.tone)}" title="${esc(item.label)}">${art(item.icon, 12, "✦")}<span class="u-sr-only">${esc(item.label)}</span></span>`
    ).join("");
    const items = (unit.items || []).map((item) =>
      `<span class="ux-unit__item" title="${esc(item.name || "道具")}">${art(item.icon, 12, "🎒")}${item.qty != null ? `<b>${esc(item.qty)}</b>` : ""}</span>`
    ).join("");
    if (!statuses && !items) return "";
    return `<span class="ux-unit__overhead" data-ux-overhead><span class="ux-unit__statuses">${statuses}</span><span class="ux-unit__items">${items}</span></span>`;
  }

  function unitInner(unit, compact = false) {
    return `${miniOverhead(unit)}<span class="ux-unit__stars" data-unit-stars>${"★".repeat(Math.max(1, number(unit.star, 1)))}</span><span class="ux-unit__avatar">${art(unit.icon, compact ? 22 : 30)}</span><span class="ux-unit__name">${esc(unit.name || "单位")}</span>${healthHtml(unit)}`;
  }

  function unitToken(unit, compact = false) {
    return `<div class="ux-unit${compact ? " ux-unit--compact" : ""}" data-ux-unit ${unitData(unit)}>${unitInner(unit, compact)}</div>`;
  }

  function logHtml(text) {
    return `<div class="ux-game-log" data-game-log role="status" aria-live="polite">${esc(text)}</div>`;
  }

  function actionButton(action, label, icon, extra = "", className = "") {
    return `<button class="ux-game-action${className ? " " + className : ""}" type="button" data-game-act="${esc(action)}" ${extra}>${icon ? art(icon, 16) : ""}<span>${esc(label)}</span></button>`;
  }

  switch (block.type) {
    case "overhead-bar": {
      const unit = { ...p, id: p.id || p.name || "player", icon: p.avatar || p.icon };
      const statuses = statusList(p).map((item) =>
        `<span class="ux-overhead__status" data-tone="${esc(item.tone)}">${art(item.icon, 13, "✦")}${esc(item.label)}</span>`
      ).join("");
      const items = (p.items || []).map((item, index) => {
        const qty = Math.max(0, number(item.qty, 1));
        const disabled = item.disabled || qty === 0;
        return `<button class="ux-overhead__item" type="button" data-game-act="use-item" data-item-index="${index}" data-item-name="${esc(item.name || "道具")}" data-qty="${qty}" data-effect="${esc(item.effect || "heal")}" data-value="${number(item.value, 10)}" aria-label="${esc(item.name || "道具")}，剩余 ${qty}" ${disabled ? "disabled" : ""}>${art(item.icon, 20, "🎒")}<span class="ux-overhead__qty" data-item-qty>${qty}</span></button>`;
      }).join("");
      return `<div class="ux-overhead" data-game-root="overhead" data-ux-overhead data-ux-unit ${unitData(unit)}><div class="ux-overhead__statuses">${statuses}</div><div class="ux-overhead__items" aria-label="头顶道具栏">${items}</div><div class="ux-overhead__avatar">${art(unit.icon, 34, "🙂")}</div><div class="ux-overhead__name">${esc(p.name || "玩家")}${p.level != null ? `<span>Lv.${esc(p.level)}</span>` : ""}</div><div class="ux-overhead__health">${healthHtml(unit)}</div></div>`;
    }

    case "turn-bar": {
      const items = p.items || [
        { icon: "refresh", label: "回合", value: p.turn ?? 1, key: "turn" },
        { icon: "clock", label: "阶段", value: p.phase || "行动中", key: "phase" },
        { icon: "zap", label: "倒计时", value: p.timer || "30s", key: "timer" },
      ];
      const chips = items.map((item) => `<span class="ux-turnbar__item"${item.tone ? ` data-tone="${esc(item.tone)}"` : ""}>${art(item.icon, 15)}<span>${esc(item.label || "")}</span><strong data-game-value="${esc(item.key || item.label || "value")}"${item.key === "turn" ? ` data-ux-turn="${esc(item.value ?? 1)}"` : ""}>${esc(item.value ?? "")}</strong></span>`).join("");
      return `<div class="ux-turnbar">${chips}</div>`;
    }

    case "slg-map": {
      const cols = clamp(Math.round(number(p.cols, 5)), 3, 8);
      const source = p.cells || [];
      const rows = clamp(Math.round(number(p.rows, Math.ceil(source.length / cols) || 5)), 2, 8);
      const cells = Array.from({ length: rows * cols }, (_, index) => {
        const cell = source[index] || {};
        const x = index % cols;
        const y = Math.floor(index / cols);
        const owner = cell.owner || "neutral";
        const terrain = cell.terrain || "plain";
        const power = Math.max(0, number(cell.power, 0));
        const label = cell.label || `${x + 1}-${y + 1}`;
        return `<button class="ux-slg__cell" type="button" role="gridcell" data-game-act="slg-select" data-ux-slot data-slot-index="${index}" data-x="${x}" data-y="${y}" data-owner="${esc(owner)}" data-terrain="${esc(terrain)}" data-power="${power}" data-label="${esc(label)}" aria-selected="false" aria-label="${esc(label)}，${esc(owner)}，兵力 ${power}"><span class="ux-slg__terrain">${art(cell.icon || (terrain === "mountain" ? "⛰️" : terrain === "water" ? "🌊" : terrain === "city" ? "🏰" : "🌾"), 22, "·")}</span><span class="ux-slg__label">${esc(label)}</span><span class="ux-slg__power" data-cell-power>${power}</span></button>`;
      }).join("");
      return `<div class="ux-slg" data-game-root="slg" data-turn="1"><div class="ux-game-status"><span>回合 <strong data-ux-turn="1" data-slg-turn>1</strong></span><span data-slg-selection>未选择地块</span></div><div class="ux-slg__layout"><div class="ux-slg__map" role="grid" aria-label="战略地图" style="--slg-cols:${cols}">${cells}</div><aside class="ux-slg__panel"><div class="ux-slg__detail" data-slg-detail>选择己方地块后，可移动或攻击相邻地块。</div><div class="ux-game-actions">${actionButton("slg-command", "侦察", "eye", 'data-command="scout" disabled')}${actionButton("slg-command", "行军", "flag", 'data-command="move" disabled')}${actionButton("slg-command", "进攻", "swords", 'data-command="attack" disabled')}${actionButton("slg-command", "取消", "x", 'data-command="cancel" disabled', "ux-game-action--ghost")}${actionButton("slg-end", "结束回合", "clock", "", "ux-game-action--primary")}</div>${logHtml(p.hint || "第一步：选择带兵力的己方地块。")}</aside></div></div>`;
    }

    case "card-battle": {
      const energy = Math.max(0, number(p.energy, 3));
      const maxEnergy = Math.max(energy, number(p.maxEnergy, 3));
