/* game-core.css — 游戏原型布局、玩法组件与反馈动画（构建时内联） */

/* 游戏默认竖屏；横屏使用宽画幅并重排 Dock，而不是旋转整页。 */
@media (min-width: 640px) {
  html[data-kind="game"][data-device="phone"][data-orientation-view="landscape"] .ux-frame {
    width: min(900px, calc(100vw - 32px));
    height: min(506px, calc(100vh - 56px));
    height: min(506px, calc(100dvh - 56px));
  }
}

html[data-kind="game"][data-orientation-view="landscape"] .ux-titlebar {
  min-height: 44px;
  padding-top: 6px;
  padding-bottom: 6px;
}
html[data-kind="game"][data-orientation-view="landscape"] .ux-scroll {
  padding: 12px;
}
html[data-kind="game"][data-orientation-view="landscape"][data-nav="dock"] .ux-screens {
  margin-right: 74px;
}
html[data-kind="game"][data-orientation-view="landscape"][data-nav="dock"] .ux-tabbar {
  left: auto;
  top: 0;
  width: 74px;
  min-height: 0;
  flex-direction: column;
  padding: 8px 6px;
  border-top: 0;
  border-left: var(--ux-border-w) solid var(--ux-line);
}
html[data-kind="game"][data-orientation-view="landscape"][data-nav="dock"] .ux-tabbar__item {
  flex: 1 1 0;
  width: 100%;
  min-height: 48px;
  max-height: 76px;
}
html[data-kind="game"][data-orientation-view="landscape"][data-nav="dock"] .ux-tabbar__item .ux-dot,
html[data-kind="game"][data-orientation-view="landscape"][data-nav="dock"] .ux-tabbar__item .ux-badge {
  left: 62%;
}
html[data-kind="game"][data-orientation-view="landscape"][data-nav="dock"] .ux-scroll {
  padding-bottom: 12px;
}
html[data-kind="game"][data-orientation-view="landscape"] .ux-toast {
  bottom: 20px;
}

/* ── 通用游戏状态与操作 ───────────────────────── */
