/* ux-core.css — skill-ux-for-app-by-web 基础样式（构建时内联，勿外链） */
/* 所有视觉差异由 :root 上的 --ux-* 变量 + data-style 覆盖驱动 */

*, *::before, *::after { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
html { -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--ux-font);
  font-size: var(--ux-fs-md);
  color: var(--ux-ink);
  background: var(--ux-bg);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}
button, input, select, textarea { font: inherit; color: inherit; }
button { cursor: pointer; border: none; background: none; padding: 0; }
img { max-width: 100%; display: block; }
a { color: var(--ux-primary); text-decoration: none; }

/* ── 舞台与设备框 ─────────────────────────────── */
.ux-stage {
  min-height: 100vh;
  min-height: 100dvh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--ux-bg);
  background-image: var(--ux-stage-bg, none);
  padding: 0;
}
.ux-frame {
  position: relative;
  width: 100%;
  max-width: 100%;
  height: 100vh;
  height: 100dvh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--ux-bg);
}
@media (min-width: 640px) {
  .ux-stage { padding: 28px 16px; }
  .ux-frame {
    width: 400px;
    height: min(860px, calc(100vh - 56px));
    height: min(860px, calc(100dvh - 56px));
    border-radius: calc(var(--ux-r-xl) + 8px);
    box-shadow:
      0 0 0 1px var(--ux-line),
      0 24px 80px rgba(0,0,0,.18),
      0 4px 16px rgba(0,0,0,.08);
  }
}
/* 桌面应用形态：更宽的工作区 */
[data-device="desktop"] .ux-frame {
  width: min(1120px, 100%);
  height: min(760px, calc(100vh - 56px));
  height: min(760px, calc(100dvh - 56px));
  border-radius: var(--ux-r-lg);
}

/* ── 屏幕栈 ───────────────────────────────────── */
.ux-screens { position: relative; flex: 1; min-height: 0; display: flex; flex-direction: column; }
.ux-screen {
  position: absolute; inset: 0;
  display: flex; flex-direction: column;
  opacity: 0; visibility: hidden;
  transform: translateX(16px);
  transition: opacity var(--ux-dur) var(--ux-ease), transform var(--ux-dur) var(--ux-ease), visibility 0s linear var(--ux-dur);
  pointer-events: none;
}
.ux-screen.is-active {
  opacity: 1; visibility: visible; transform: none;
  transition: opacity var(--ux-dur) var(--ux-ease), transform var(--ux-dur) var(--ux-ease), visibility 0s;
  pointer-events: auto;
}
.ux-screen.is-back { transform: translateX(-16px); }
.ux-scroll {
  flex: 1; min-height: 0; overflow-y: auto; overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
  padding: var(--ux-pad);
  padding-bottom: calc(var(--ux-pad) + 12px);
